class Canvas:
    """An RGB pixel buffer with tiny drawing helpers (no dependencies)."""

    def __init__(self, width, height, color):
        self.width = width
        self.height = height
        self.pixels = bytearray(bytes(color) * width * height)

    def set_pixel(self, x, y, color):
        if 0 <= x < self.width and 0 <= y < self.height:
            i = (y * self.width + x) * 3
            self.pixels[i:i + 3] = bytes(color)

    def fill_rect(self, x0, y0, x1, y1, color):
        x0 = max(0, x0)
        y0 = max(0, y0)
        x1 = min(self.width, x1)
        y1 = min(self.height, y1)
        row = bytes(color) * (x1 - x0)
        for y in range(y0, y1):
            i = (y * self.width + x0) * 3
            self.pixels[i:i + len(row)] = row

    def hline(self, x0, x1, y, color, width=1):
        for w in range(width):
            for x in range(min(x0, x1), max(x0, x1) + 1):
                self.set_pixel(x, y + w, color)

    def vline(self, x, y0, y1, color, width=1):
        for w in range(width):
            for y in range(min(y0, y1), max(y0, y1) + 1):
                self.set_pixel(x + w, y, color)

    def line(self, x0, y0, x1, y1, color, width=1):
        dx = abs(x1 - x0)
        dy = -abs(y1 - y0)
        sx = 1 if x0 < x1 else -1
        sy = 1 if y0 < y1 else -1
        err = dx + dy
        while True:
            for w in range(width):
                self.set_pixel(x0 + w, y0, color)
            if x0 == x1 and y0 == y1:
                break
            e2 = 2 * err
            if e2 >= dy:
                err += dy
                x0 += sx
            if e2 <= dx:
                err += dx
                y0 += sy

    def disc(self, cx, cy, r, color):
        for dy in range(-r, r + 1):
            half = int((r * r - dy * dy) ** 0.5)
            self.hline(cx - half, cx + half, cy + dy, color)

    def ring(self, cx, cy, r, color):
        for dy in range(-r, r + 1):
            half = int((r * r - dy * dy) ** 0.5)
            self.set_pixel(cx - half, cy + dy, color)
            self.set_pixel(cx + half, cy + dy, color)

    def char_width(self, scale):
        return 6 * scale

    def text_width(self, text, scale):
        return len(text) * 6 * scale - scale

    def draw_char(self, x, y, char, scale, color):
        glyph = FONT.get(char)
        if glyph is None:
            return
        for row in range(7):
            bits = glyph[row]
            for col in range(5):
                if bits & (1 << (4 - col)):
                    self.fill_rect(x + col * scale, y + row * scale,
                                   x + (col + 1) * scale,
                                   y + (row + 1) * scale, color)

    def text(self, x, y, s, scale, color, anchor="left"):
        s = s.upper()
        if anchor == "center":
            x -= self.text_width(s, scale) // 2
        elif anchor == "right":
            x -= self.text_width(s, scale)
        for char in s:
            self.draw_char(x, y, char, scale, color)
            x += 6 * scale

    def wrap(self, s, scale, max_w):
        """Greedy word wrap; returns a list of lines fitting max_w pixels."""
        words = s.upper().split()
        lines, cur = [], ""
        for word in words:
            trial = word if not cur else cur + " " + word
            if self.text_width(trial, scale) <= max_w:
                cur = trial
            else:
                if cur:
                    lines.append(cur)
                cur = word
        if cur:
            lines.append(cur)
        return lines

    def rows(self):
        stride = self.width * 3
        return [bytes(self.pixels[y * stride:(y + 1) * stride])
                for y in range(self.height)]

    def to_png(self):
        return png_bytes(self.width, self.height, self.rows())


