def project(lon, lat, box):
    x0, y0, x1, y1 = box
    x = x0 + (lon + 180.0) / 360.0 * (x1 - x0)
    y = y0 + (90.0 - lat) / 180.0 * (y1 - y0)
    return x, y


def fill_polygon(canvas, points, color):
    ys = [p[1] for p in points]
    n = len(points)
    for y in range(min(ys), max(ys) + 1):
        xs = []
        for i in range(n):
            x0, y0 = points[i]
            x1, y1 = points[(i + 1) % n]
            if (y0 <= y < y1) or (y1 <= y < y0):
                xs.append(x0 + (y - y0) * (x1 - x0) / (y1 - y0))
        xs.sort()
        for i in range(0, len(xs) - 1, 2):
            canvas.hline(int(xs[i]), int(xs[i + 1]), y, color)


def draw_fallback_page():
    """Draw a simplified front page with the stdlib canvas. Returns PNG bytes."""
    paper = (250, 246, 238)
    ink = (24, 24, 24)
    soft = (90, 86, 80)
    red = (176, 32, 32)
    hair = (190, 184, 174)
    ocean = (214, 226, 232)
    land = (245, 241, 232)
    land_edge = (150, 142, 128)
    white = (255, 255, 255)
    pic_cols = [(58, 72, 88), (28, 78, 92), (34, 74, 60)]

    page = Canvas(1024, 1024, paper)
    mx = 28
    right = 1024 - mx
    cw = right - mx

    # ---- masthead ---------------------------------------------------
    page.fill_rect(mx, 16, mx + 96, 78, red)
    page.text(mx + 48, 26, "NOV 20", 2, white, anchor="center")
    page.text(mx + 48, 48, "FRI 2026", 1, white, anchor="center")
    page.text(mx + 108, 20, "THE DAY IN WORLD NEWS", 2, ink)
    page.text(mx + 108, 42, "Friday 20 November 2026", 4, ink)
    page.text(right, 24, "45 STORIES - 7 REGIONS - ONE PAGE", 2, ink,
              anchor="right")
    page.hline(mx, right, 108, ink, 3)

    # ---- region strip -----------------------------------------------
    page.text(512, 116, "EUROPE 9 - AMERICAS 9 - ASIA 7 - AFRICA 5 - "
              "MIDDLE EAST 5 - OCEANIA 5 - WORLD 5", 2, ink, anchor="center")
    page.hline(mx, right, 134, ink, 1)

    # ---- the day in numbers ------------------------------------------
    page.text(mx, 142, "THE DAY IN NUMBERS", 2, red)
    col_w = cw // 6
    for i, (num, label) in enumerate(NUMBERS_FB):
        x = mx + i * col_w
        if i:
            page.vline(x - 8, 158, 182, hair, 1)
        page.text(x, 154, num, 3, ink)
        for j, line in enumerate(page.wrap(label, 1, col_w - 8)):
            page.text(x, 180 + j * 9, line, 1, soft)
    page.hline(mx, right, 196, ink, 2)

    # ---- three headline cards ----------------------------------------
    gap = 14
    card_w = (cw - 2 * gap) // 3
    img_h = 104
    y0 = 206
    for i, (kicker, title, deck) in enumerate(HEADLINES_FB):
        x = mx + i * (card_w + gap)
        page.fill_rect(x, y0, x + card_w, y0 + img_h, pic_cols[i])
        page.text(x + card_w // 2, y0 + img_h // 2 - 7,
                  "PICTURE " + str(i + 1), 2, white, anchor="center")
        page.hline(x, x + card_w, y0 + img_h, hair, 1)
        ky = y0 + img_h + 8
        page.text(x, ky, kicker, 1, red)
        ty = ky + 14
        title_lines = page.wrap(title, 2, card_w)
        for j, line in enumerate(title_lines):
            page.text(x, ty + j * 18, line, 2, ink)
        dy = ty + len(title_lines) * 18 + 4
        for j, line in enumerate(page.wrap(deck, 1, card_w)[:3]):
            page.text(x, dy + j * 10, line, 1, soft)
    page.hline(mx, right, 448, ink, 2)

    # ---- world map ----------------------------------------------------
    page.text(mx, 456, "WHERE IT HAPPENED - STORIES PINNED BY NUMBER", 2, ink)
    map_box = (mx, 476, right, 636)
    page.fill_rect(mx, 476, right, 636, ocean)
    for poly in LAND_FB:
        pts = [(int(px), int(py)) for px, py in
               (project(lon, lat, map_box) for lon, lat in poly)]
        fill_polygon(page, pts, land)
    for num, lat, lon in PINS_FB:
        x, y = project(lon, lat, map_box)
        page.disc(int(x), int(y), 8, red)
        page.ring(int(x), int(y), 8, white)
        page.text(int(x), int(y) - 4, str(num), 1, white, anchor="center")
    page.hline(mx, right, 644, ink, 2)

    # ---- also on -------------------------------------------------------
    page.text(mx, 652, "ALSO ON FRIDAY 20 NOVEMBER", 2, ink)
    cols = 4
    col_gap = 16
    col_w = (cw - (cols - 1) * col_gap) // cols
    rows = 11
    for idx, item in enumerate(ALSO_FB):
        num, title = item.split("|", 1)
        col = idx // rows
        row = idx % rows
        x = mx + col * (col_w + col_gap)
        y = 676 + row * 19
        page.text(x, y, num, 1, red)
        # First wrapped line only, so long titles never spill into the
        # next column.
        page.text(x + 24, y, page.wrap(title, 1, col_w - 24)[0], 1, ink)
    also_bot = 676 + rows * 19
    page.hline(mx, right, also_bot + 2, ink, 2)

    # ---- date check -----------------------------------------------------
    dy0 = also_bot + 10
    page.text(mx, dy0, "DATE CHECK - LEFT OUT ON PURPOSE", 2, red)
    half = cw // 2
    for i, item in enumerate(DATECHECK_FB):
        col = i // 4
        row = i % 4
        x = mx + col * half
        y = dy0 + 20 + row * 11
        page.text(x, y, "X  " + item, 1, soft)
    box_top = dy0 - 4
    box_bot = dy0 + 20 + 3 * 11 + 10
    page.vline(mx - 6, box_top, box_bot, red, 1)
    page.vline(right + 6, box_top, box_bot, red, 1)
    page.hline(mx - 6, right + 6, box_top, red, 1)
    page.hline(mx - 6, right + 6, box_bot, red, 1)

    # ---- footer ----------------------------------------------------------
    foot = ("Every story happened on, or was first reported on, Friday 20 "
            "November 2026. Sources: Reuters, CNN, Le Monde, Toronto Star, "
            "UN News, Phys.org, The Hindu, Daily Baku, AppiSToS, RNZ Pacific, "
            "Dubai Standard. Original drawings.")
    for j, line in enumerate(page.wrap(foot, 1, cw)):
        page.text(mx, box_bot + 8 + j * 11, line, 1, soft)

    return page.to_png()


if __name__ == "__main__":
    main()
